    body{margin:0;font-family:Arial,sans-serif;background:#fff;color:#1b1f24}
    .wrap{width:1400px;height:900px;padding:36px 44px;box-sizing:border-box}
    h1{margin:0 0 14px;font-size:34px;line-height:1.2}
    .sub{margin:0 0 14px;color:#4b5563;font-size:18px}
    .chartBox{height:720px;border:1px solid #d1d5db;border-radius:12px;padding:16px 18px 8px 8px;box-sizing:border-box;background:#fff}
    canvas{width:100% !important;height:100% !important}
  </style>
</head>
<body>
  <div class="wrap">
    <h1>${esc(goal)}</h1>
    <p class="sub">Unit: Percent of global electricity generation (%)</p>
    <div class="chartBox">
      <canvas id="c" role="img" aria-label="Line chart of clean energy share over time"></canvas>
    </div>
  </div>
  <script>
    const ctx = document.getElementById('c');
    new Chart(ctx, {
      type: 'line',
      data: {
        labels: ${JSON.stringify(years)},
        datasets: [{
          label: 'Clean energy share (%)',
          data: ${JSON.stringify(vals)},
          borderColor: '#1f77b4',
          backgroundColor: 'rgba(31,119,180,0.12)',
          fill: true,
          tension: 0.25,
          pointRadius: 3,
          pointHoverRadius: 4,
          borderWidth: 3
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { display: true, position: 'top', labels: { boxWidth: 26 } },
          tooltip: { enabled: true },
          title: { display: false }
        },
        scales: {
          x: { title: { display: true, text: 'Year' }, grid: { display: false } },
          y: { title: { display: true, text: 'Clean Energy Share (%)' }, ticks: { callback: (v)=>v+'%' }, grid: { color: '#e5e7eb' } }
        }
      }
    });
  </script>
</body>
</html>`;

fs.writeFileSync('/tmp/chart.html', html);
